INSERT INTO vocab_library_words VALUES ('14296bf9-ba0c-472b-a344-3dab9ccefd59', '566b580e-d294-48cc-a355-5a28a08eb500', 'opponent', '(주장·논쟁의) 반대자', '{adversary,detractor}', '{supporter,proponent}', 'Opponents of the bill argue that it will raise costs for consumers.', 'The debate pitted the proposal''s supporters against its opponents.', 183, '2026-09-16 07:46:50.470658+00', 2, '논쟁 구도 설명에 필요한 기본 명사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('6bd7e505-e7f9-4ff0-b7ca-41f5fb51b3ce', '566b580e-d294-48cc-a355-5a28a08eb500', 'emphasis', '강조점, 역점', '{stress,focus}', '{neglect,disregard}', 'The article places heavy emphasis on individual responsibility.', 'Recent research has shifted its emphasis toward environmental factors.', 184, '2026-09-16 07:46:50.470658+00', 2, '논증 지문에서 강조 대상을 나타내는 명사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('d1f14331-3513-4ad9-abe9-1e06be538599', '566b580e-d294-48cc-a355-5a28a08eb500', 'debate', '논쟁, 논의하다', '{dispute,discussion}', '{agreement,consensus}', 'The essay contributes to an ongoing debate about educational reform.', 'Scholars continue to debate the true causes of the decline.', 185, '2026-09-16 07:46:50.470658+00', 2, '논증형 지문의 기본 소재를 나타내는 명사·동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('da6e5be0-12f2-4f7e-a308-11a1d1c917ca', '566b580e-d294-48cc-a355-5a28a08eb500', 'grounds', '(주장의) 근거, 이유', '{basis,justification}', '{<UNKNOWN>,<UNKNOWN>}', 'The author provides solid grounds for rejecting the traditional view.', 'There are insufficient grounds to support such a sweeping conclusion.', 186, '2026-09-16 07:46:50.470658+00', 2, '논거 제시 표현으로 논증 분석 문제 고빈도') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('ea5a8428-759a-4d0d-9811-06bbee5be4d4', '566b580e-d294-48cc-a355-5a28a08eb500', 'counterbalance', '균형을 맞추다, 상쇄하다(반대 입장으로)', '{offset,neutralize}', '{intensify,aggravate}', 'The author uses a concession to counterbalance the strength of the opposing view.', 'One benefit does not counterbalance the significant risks outlined earlier in the passage.', 187, '2026-09-16 07:46:50.470658+00', 3, '찬반 균형을 다루는 논증 지문에서 자주 활용되는 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('4f33e1cb-7f2b-4cf3-91bd-b76a1bd9b9b3', '566b580e-d294-48cc-a355-5a28a08eb500', 'counterexample', '(주장을 반박하는) 반례', '{exception,anomaly}', '{confirmation,illustration}', 'The critic offers a counterexample to show that the author''s generalization does not always hold.', 'One counterexample was enough to weaken the entire theoretical framework.', 188, '2026-09-16 07:46:50.470658+00', 3, '논증 구조 분석 지문에서 반박 전략을 설명할 때 등장하는 명사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('15a3de0d-da75-424e-8808-b5ebd8a24c23', '566b580e-d294-48cc-a355-5a28a08eb500', 'overgeneralize', '지나치게 일반화하다, 과도하게 확대 해석하다', '{oversimplify,extrapolate}', '{qualify,specify}', 'The author is careful not to overgeneralize from a single case study.', 'Critics argued that the report overgeneralizes trends based on limited data.', 189, '2026-09-16 07:46:50.470658+00', 3, '논리적 오류 분석 지문에서 자주 등장하는 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('f2352bee-89fe-46f3-8aaf-89f34e2bc807', '566b580e-d294-48cc-a355-5a28a08eb500', 'sway', '(의견·주장으로) 설득하다, 영향을 미치다', '{persuade,influence}', '{dissuade,deter}', 'The persuasive essay was designed to sway public opinion on immigration policy.', 'Compelling statistics can sway even the most skeptical readers.', 190, '2026-09-16 07:46:50.470658+00', 2, '설득 전략 분석 지문에서 자주 등장하는 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('1849fd76-28f3-4429-81b1-ad902d9d915f', '566b580e-d294-48cc-a355-5a28a08eb500', 'probe', '면밀히 조사하다, 캐묻다', '{investigate,examine}', '{ignore,overlook}', 'The journalist''s article probes the motives behind the corporation''s decision.', 'The committee probed the inconsistencies in the witness''s testimony.', 191, '2026-09-16 07:46:50.470658+00', 3, '비판적 분석 지문의 조사 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('05fd0a0d-f7e2-487e-96e9-881d104ceb06', '566b580e-d294-48cc-a355-5a28a08eb500', 'deride', '조롱하다, 폄하하다', '{mock,scorn}', '{praise,commend}', 'The critic derides the proposal as naive and impractical.', 'Opponents derided the plan without offering any alternative.', 192, '2026-09-16 07:46:50.470658+00', 3, '논쟁적 어조 분석에 쓰이는 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('14b319f1-7f0f-4815-b664-1309560ab930', '566b580e-d294-48cc-a355-5a28a08eb500', 'bemoan', '한탄하다, 개탄하다', '{lament,deplore}', '{celebrate,applaud}', 'The essay bemoans the decline of civic engagement among young voters.', 'He bemoaned the lack of funding for public education.', 193, '2026-09-16 07:46:50.470658+00', 3, '사설 어조 표현의 감정적 주장 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('0cbfecd0-dc7c-4e30-a93f-c69fd5f77fd7', '566b580e-d294-48cc-a355-5a28a08eb500', 'affirmation', '확언, 단언(주장을 확실히 함)', '{assertion,declaration}', '{denial,retraction}', 'The senator''s affirmation of her original policy left little room for compromise.', 'Critics viewed the report''s affirmation of the earlier study as premature, given the limited data.', 194, '2026-09-16 07:46:50.470658+00', 2, '논증형 에세이·사설 지문에서 주장을 명시할 때 자주 등장하는 명사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('92d05d44-bfa2-4bef-aaef-7d08495b7a33', '566b580e-d294-48cc-a355-5a28a08eb500', 'opposition', '반대, 반론(제기된 주장에 맞서는 입장)', '{resistance,dissent}', '{support,agreement}', 'The editorial faced strong opposition from readers who disagreed with its central argument.', 'Despite fierce opposition, the author refused to soften her controversial claim.', 195, '2026-09-16 07:46:50.470658+00', 2, '찬반 논쟁 구조의 지문에서 반대 입장을 나타내는 핵심 명사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('5ed7e8a8-1c4c-41a0-8d0a-5637980d519b', '566b580e-d294-48cc-a355-5a28a08eb500', 'rebuke', '(주장·행동을) 강하게 비판하다, 질책하다', '{reprimand,chastise}', '{praise,commend}', 'The columnist issued a sharp rebuke of the government''s inconsistent reasoning.', 'Historians rebuked the outdated theory once new evidence surfaced.', 196, '2026-09-16 07:46:50.470658+00', 3, '논쟁적 사설에서 강한 비판을 표현할 때 등장하는 동사') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('9afa8c42-7c27-49cc-9cb8-ee497313717d', '566b580e-d294-48cc-a355-5a28a08eb500', 'detract', '(가치·설득력을) 떨어뜨리다, 손상시키다', '{diminish,lessen}', '{enhance,strengthen}', 'A single weak example detracted from the overall strength of her argument.', 'The author''s overly emotional tone detracted from the credibility of his claim.', 197, '2026-09-16 07:46:50.470658+00', 3, '논증 평가 지문에서 주장의 설득력 저하를 서술할 때 빈출') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('5715d42a-dcc2-4981-a844-893be0697f59', '566b580e-d294-48cc-a355-5a28a08eb500', 'dismissive', '(주장 등을) 무시하는, 경시하는', '{disdainful,scornful}', '{respectful,receptive}', 'The critic''s dismissive tone toward opposing views weakened his overall credibility.', 'Readers found the editorial''s dismissive treatment of counterarguments unconvincing.', 198, '2026-09-16 07:46:50.470658+00', 3, '논증 태도 분석 지문에서 화자의 부정적 태도를 나타낼 때 사용') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('c646c09f-f6e7-4829-bde5-84b1c7687869', '566b580e-d294-48cc-a355-5a28a08eb500', 'dismissal', '(주장·의견 등을) 일축함, 묵살', '{rejection,disregard}', '{acceptance,endorsement}', 'The critic''s dismissal of the opposing theory struck many readers as overly hasty.', 'Her outright dismissal of the counterevidence weakened the overall persuasiveness of her essay.', 199, '2026-09-16 07:46:50.470658+00', 3, '사설 지문에서 상대 논거를 처리하는 방식을 설명할 때 등장하는 명사') ON CONFLICT DO NOTHING;
